// Stub of qollab_project/ui_api.py for local UI testing (dev/index.html maps the
// bare specifier "ui_api" here with an import map). Same function names; each is a
// function with .callPromising(...) that resolves to a JSON string, like a Pyodide
// PyProxy. Answers come from dev/stub_data.js, generated by tools/make_ui_stubs.py
// from the REAL ui_api functions. The noise dial interpolates between grid points;
// interpolated readings are marked "[stub: interpolated]". Not uploaded to Qollab.

import { STUB } from "./stub_data.js";

const params = new URLSearchParams(globalThis.location ? globalThis.location.search : "");
const SLOW = Number(params.get("slow") || 1);   // ?slow=3 triples every delay
let jobsThisLoad = 0;

function asPy(fn, delayMs) {
  const f = (...args) => fn(...args);
  f.callPromising = (...args) => new Promise((resolve, reject) => {
    setTimeout(() => {
      try { resolve(fn(...args)); } catch (err) { reject(err); }
    }, delayMs * SLOW);
  });
  return f;
}

function kindOf(backend) {
  const k = backend && backend.stubKind;
  return k && STUB.profiles[k] ? k : "basic";
}

// ------------------------------------------------------------------ noise dial
function lerp(a, b, t) {
  if (typeof a === "number" && typeof b === "number") return a + (b - a) * t;
  if (Array.isArray(a) && Array.isArray(b)) return a.map((v, i) => lerp(v, b[i], t));
  if (a && b && typeof a === "object" && typeof b === "object") {
    const out = {};
    for (const k of Object.keys(a)) out[k] = lerp(a[k], b[k], t);
    return out;
  }
  return t < 0.5 ? a : b;
}

function bracket(grid, x) {
  if (x <= grid[0]) return [0, 0, 0];
  for (let i = 1; i < grid.length; i++) {
    if (x <= grid[i]) return [i - 1, i, (x - grid[i - 1]) / (grid[i] - grid[i - 1])];
  }
  const n = grid.length - 1;
  return [n, n, 0];
}

function finish(resp, exact) {
  const S = resp.S;
  const exceeds = S > 2 + 1e-12;
  resp.exceeds = exceeds;
  resp.margin = S - 2;
  if (!exact) {
    let sd2 = 0;
    for (const t of resp.terms) sd2 += t.coef * t.coef * Math.max(0, 1 - t.E * t.E);
    resp.shots_per_setting_3sigma = exceeds ? Math.max(1, Math.ceil(9 * sd2 / ((S - 2) * (S - 2)))) : null;
    resp.reading = "[stub: interpolated] Under this noise model quantum theory predicts S = " + S.toFixed(3) +
      (exceeds ? ", above the classical bound of 2 by " + (S - 2).toFixed(3) + "; about " +
        resp.shots_per_setting_3sigma.toLocaleString("en-US") + " shots per setting would put a run 3 standard errors above the bound."
        : ", at or below the classical bound of 2, so no number of shots would show a CHSH violation at this noise level.");
  }
  const shared = STUB.dial.shared;
  return Object.assign({
    outcome_key_order: shared.outcome_key_order,
    settings_degrees: shared.settings_degrees,
    classical_bound: shared.classical_bound,
    quantum_ideal: shared.quantum_ideal,
    sim_note: shared.sim_note,
    preset_note: resp.preset === "custom" ? null : shared.preset_note_ionq,
  }, resp);
}

function dial(p) {
  const D = STUB.dial;
  const preset = p.preset || "custom";
  if (preset === "custom") {
    const p2 = Number(p.p2 || 0);
    const ro = Number(p.r01 || 0);
    const at = (i, j) => D.custom[j * D.p2_grid.length + i].resp;
    const [i0, i1, tx] = bracket(D.p2_grid, p2);
    const [j0, j1, ty] = bracket(D.ro_grid, ro);
    const resp = lerp(lerp(at(i0, j0), at(i1, j0), tx), lerp(at(i0, j1), at(i1, j1), tx), ty);
    const exact = (tx === 0 || tx === 1) && (ty === 0 || ty === 1);
    resp.noise = { p1: 0, p2, readout: [ro, ro], scale: 1, effective: { p1: 0, p2, r01: ro, r10: ro } };
    return finish(resp, exact);
  }
  const rows = D.presets[preset];
  if (!rows) return { error: "ValueError: preset must be one of custom, ionq_forte_like, ionq_forte_like_spam, got '" + preset + "'" };
  const scale = Number(p.scale ?? 1);
  const [i0, i1, t] = bracket(D.scale_grid, scale);
  const resp = lerp(rows[i0].resp, rows[i1].resp, t);
  resp.noise.scale = scale;
  return finish(resp, t === 0 || t === 1);
}

// ------------------------------------------------------------------ exports
export const profile_json = asPy((backend, newRun) => {
  if (newRun === true) jobsThisLoad = 0;   // like ui_api: main.js marks the start of a run
  const p = Object.assign({}, STUB.profiles[kindOf(backend)]);
  p.jobs_this_session = jobsThisLoad;
  p.run_allowed = !(p.one_job && jobsThisLoad >= 1);
  return JSON.stringify(p);
}, 60);

export const noise_dial_json = asPy((paramsJson) => JSON.stringify(dial(JSON.parse(paramsJson || "{}"))), 25);

export const run_chsh_json = asPy((backend, shots, mode, mitigate) => {
  const kind = kindOf(backend);
  const profile = STUB.profiles[kind];
  if (profile.one_job && jobsThisLoad >= 1) return JSON.stringify(STUB.runs[kind + ":refused"]);
  const key = kind + ":" + (mitigate ? "mit" : "raw");
  const run = STUB.runs[key] || STUB.runs[kind + ":mit"];
  if (run.job_submitted !== false) jobsThisLoad += 1;
  console.warn("[stub] canned run '" + key + "' (" + STUB.shots + " shots, mode auto); requested shots=" +
    shots + ", mode=" + mode + " are not simulated in stub mode");
  return JSON.stringify(run);
}, 900);

export const curve_json = asPy(() => JSON.stringify(STUB.curve), 80);

export const card_text_json = asPy((cardJson) => {
  const card = JSON.parse(cardJson);
  const id = card && card.provenance && card.provenance.job && card.provenance.job.job_id;
  const hit = STUB.card_texts[id];
  return JSON.stringify(hit || { error: "stub: no canned text for this card" });
}, 20);
